-- Migration 003: Spaced Repetition — Flashcards
-- Adds flashcards (AI-generated per lesson) and per-learner SM-2 progress tracking.

-- ============ FLASHCARDS ============
-- Stores front/back pairs generated by AI for each lesson

CREATE TABLE IF NOT EXISTS flashcards (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  lesson_id    UUID NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  front        TEXT NOT NULL,          -- question / prompt side
  back         TEXT NOT NULL,          -- answer / explanation side
  sequence_order INTEGER NOT NULL DEFAULT 0,
  created_at   TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_flashcards_lesson ON flashcards(lesson_id);

-- ============ FLASHCARD PROGRESS ============
-- Tracks each learner's SM-2 state per flashcard

CREATE TABLE IF NOT EXISTS flashcard_progress (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  learner_id      UUID NOT NULL REFERENCES learners(id) ON DELETE CASCADE,
  flashcard_id    UUID NOT NULL REFERENCES flashcards(id) ON DELETE CASCADE,
  due_date        TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  interval_days   INTEGER         DEFAULT 1,    -- days until next review
  ease_factor     DECIMAL(4,2)    DEFAULT 2.50, -- SM-2 ease factor (min 1.3)
  reps            INTEGER         DEFAULT 0,    -- consecutive successful reviews
  lapses          INTEGER         DEFAULT 0,    -- times the card was forgotten
  last_review_at  TIMESTAMP WITH TIME ZONE,
  created_at      TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at      TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  UNIQUE(learner_id, flashcard_id)
);

CREATE INDEX IF NOT EXISTS idx_fp_learner     ON flashcard_progress(learner_id);
CREATE INDEX IF NOT EXISTS idx_fp_due         ON flashcard_progress(learner_id, due_date);
CREATE INDEX IF NOT EXISTS idx_fp_flashcard   ON flashcard_progress(flashcard_id);
